// MCP OAuth end to end against a local server with DEV_AUTH=1 and FILE_LINK_SECRET set (see
// .dev.vars.example). Usage: npm run smoke:oauth, with AWAIT_BASE_URL for another origin.
import { createHash, randomBytes } from 'node:crypto';
import WebSocket from 'ws';
import assert from 'node:assert/strict';

const base = process.env.AWAIT_BASE_URL ?? 'http://127.0.0.1:5173';
const email = `oauth-smoke-${Date.now()}@localhost`;
const json = async (response) => {
  const body = await response.json();
  if (!response.ok) throw new Error(`${response.status}: ${JSON.stringify(body)}`);
  return body;
};
const login = await fetch(`${base}/api/dev/login`, { method: 'POST', headers: { 'content-type': 'application/json' }, body: JSON.stringify({ name: 'OAuth tester', email }) });
await json(login);
const sessionCookie = login.headers.get('set-cookie')?.split(';')[0];
if (!sessionCookie) throw new Error('Dev sign-in cookie missing.');
const authHeaders = { cookie: sessionCookie, 'content-type': 'application/json' };
const workspace = await json(await fetch(`${base}/api/workspaces`, { method: 'POST', headers: authHeaders, body: JSON.stringify({ name: 'OAuth Test' }) }));
const client = await json(await fetch(`${base}/register`, { method: 'POST', headers: { 'content-type': 'application/json' }, body: JSON.stringify({ client_name: 'Await OAuth smoke', redirect_uris: ['http://127.0.0.1:8765/callback'], grant_types: ['authorization_code', 'refresh_token'], response_types: ['code'], token_endpoint_auth_method: 'none' }) }));
const verifier = randomBytes(32).toString('base64url');
const challenge = createHash('sha256').update(verifier).digest('base64url');
const authorization = new URL(`${base}/authorize`);
for (const [key, value] of Object.entries({ response_type: 'code', client_id: client.client_id, redirect_uri: 'http://127.0.0.1:8765/callback', scope: 'read post files', state: 'test-state', code_challenge: challenge, code_challenge_method: 'S256', resource: `${base}/mcp` })) authorization.searchParams.set(key, value);
const consent = await fetch(authorization, { headers: { cookie: sessionCookie }, redirect: 'manual' });
const html = await consent.text();
if (!consent.ok || !html.includes('Connect Await OAuth smoke to Await')) throw new Error(`Consent page failed: ${consent.status} ${html.slice(0, 500)}`);
if (!html.includes('Write messages, tasks, and documents') || !html.includes('MCP Events')) throw new Error('Consent must explain writing and native event monitoring.');
const handle = html.match(/name="handle" value="([^"]+)"/)?.[1];
if (!handle) throw new Error('Consent handle missing.');
const consentCookie = consent.headers.get('set-cookie')?.split(';')[0];
if (!consentCookie) throw new Error('Consent cookie missing.');
const form = new URLSearchParams({ handle, agent_id: '', new_agent_name: 'OAuth Tester Agent', workspace_id: workspace.id, initial_channel_id: workspace.channel_id, decision: 'approve' });
form.append('scope', 'read');
form.append('scope', 'post');
form.append('scope', 'files');
const approved = await fetch(`${base}/authorize`, { method: 'POST', headers: { cookie: `${sessionCookie}; ${consentCookie}`, 'content-type': 'application/x-www-form-urlencoded', origin: base }, body: form, redirect: 'manual' });
const redirect = approved.headers.get('location');
if (approved.status !== 302 || !redirect) throw new Error(`Approval failed: ${approved.status} ${await approved.text()}`);
const code = new URL(redirect).searchParams.get('code');
if (!code) throw new Error(`Authorization code missing: ${redirect}`);
const token = await json(await fetch(`${base}/oauth/token`, { method: 'POST', headers: { 'content-type': 'application/x-www-form-urlencoded' }, body: new URLSearchParams({ grant_type: 'authorization_code', code, redirect_uri: 'http://127.0.0.1:8765/callback', client_id: client.client_id, code_verifier: verifier, resource: `${base}/mcp` }) }));
if (!token.access_token) throw new Error('Access token missing.');
const rpc = async (id, method, params) => json(await fetch(`${base}/mcp`, { method: 'POST', headers: { authorization: `Bearer ${token.access_token}`, 'content-type': 'application/json' }, body: JSON.stringify({ jsonrpc: '2.0', id, method, params }) }));
const initialized = await rpc(1, 'initialize');
if (initialized.result?.serverInfo?.name !== 'await.chat') throw new Error('MCP initialize failed.');
if (initialized.result?.capabilities?.experimental?.['openai/settings']?.readTool !== 'settings.read' || initialized.result.capabilities.experimental['openai/settings'].updateTool !== 'settings.update') throw new Error('Native plugin settings are missing.');
const snapshot = await json(await fetch(`${base}/api/workspaces/${workspace.id}/snapshot`, { headers: { cookie: sessionCookie } }));
const agent = snapshot.members.find((member) => member.name === 'OAuth Tester Agent');
if (!agent) throw new Error('Created agent missing from workspace.');
const context = await rpc(19, 'tools/call', { name: 'get_agent_context', arguments: {} });
if (context.result?.isError || context.result?.structuredContent?.result?.agent?.name !== 'OAuth Tester Agent' || !context.result?.structuredContent?.result?.channels?.some((channel) => channel.id === workspace.channel_id)) throw new Error('New OAuth agent did not start with channel access.');
const listedTools = await rpc(20, 'tools/list');
if (!listedTools.result?.tools?.find((tool) => tool.name === 'settings.read')?.outputSchema || !listedTools.result.tools.find((tool) => tool.name === 'settings.update')?.outputSchema) throw new Error('Plugin settings tool schemas are missing.');
const profileTool = listedTools.result.tools.find((tool) => tool.name === 'get_profile');
assert.equal(profileTool?._meta?.['openai/profile'], true);
assert.deepEqual(profileTool?.inputSchema, { type: 'object', properties: {}, additionalProperties: false });
assert.deepEqual(profileTool?.outputSchema?.required, ['id']);
assert.equal(profileTool?.outputSchema?.additionalProperties, false);
const originalProfileResponse = await rpc(202, 'tools/call', { name: 'get_profile', arguments: {} });
const originalProfile = originalProfileResponse.result?.structuredContent;
assert.match(originalProfile?.id, /^prf_/);
assert.equal(originalProfile?.nickname, 'OAuth Tester Agent · OAuth Test');
assert.equal(originalProfile?.email, undefined, 'Agent profiles must not reveal their owner email');
assert.equal(originalProfile?.result, undefined, 'Profile must be a top-level structured object');
assert.deepEqual(JSON.parse(originalProfileResponse.result.content[0].text), originalProfile);
assert.equal((await rpc(203, 'tools/call', { name: 'get_profile', arguments: {} })).result.structuredContent.id, originalProfile.id);
const agentSettings = await rpc(200, 'tools/call', { name: 'settings.read', arguments: {} });
if (agentSettings.result?.isError || Object.keys(agentSettings.result?.structuredContent?.schema?.properties ?? {}).length) throw new Error('Agent connection exposed human email settings.');
const agentSettingsUpdate = await rpc(201, 'tools/call', { name: 'settings.update', arguments: { set: { email_mentions: true } } });
if (!agentSettingsUpdate.result?.isError) throw new Error('Agent changed a person’s email preferences.');
for (const tool of listedTools.result?.tools ?? []) {
  if (!['readOnlyHint', 'destructiveHint', 'openWorldHint'].every((key) => typeof tool.annotations?.[key] === 'boolean')) throw new Error(`MCP tool ${tool.name} has incomplete safety annotations.`);
}
for (const [name, annotation, expected] of [['post_message', 'destructiveHint', true], ['update_document', 'destructiveHint', true], ['search_gifs', 'openWorldHint', true], ['get_live_ticket', 'readOnlyHint', false], ['read_messages', 'readOnlyHint', true]]) {
  const tool = listedTools.result?.tools?.find((item) => item.name === name);
  if (tool?.annotations?.[annotation] !== expected) throw new Error(`MCP tool ${name} has incorrect ${annotation}.`);
}
const viewTool = listedTools.result?.tools?.find((tool) => tool.name === 'show_channel');
if (viewTool?._meta?.ui?.resourceUri !== 'ui://await/channel-v6.html') throw new Error('MCP channel view tool is missing its UI resource.');
const workspaceTool = listedTools.result?.tools?.find((tool) => tool.name === 'open_workspace');
if (!workspaceTool?._meta?.['openai/ui']?.entrypoints?.some((entry) => entry.type === 'global') || !workspaceTool?._meta?.['openai/ui']?.entrypoints?.some((entry) => entry.type === 'thread') || !/^ui:\/\/await\/workspace-v\d+\.html$/.test(workspaceTool?._meta?.ui?.resourceUri ?? '') || !workspaceTool.icons?.[0]?.src?.includes('/plugin-icon.svg')) throw new Error('Codex workspace entrypoints are missing.');
for (const name of ['create_agent', 'add_agent_to_channel', 'pause_agent', 'rotate_agent_token']) if (!listedTools.result?.tools?.find((tool) => tool.name === name)?._meta?.ui?.visibility?.includes('app')) throw new Error(`${name} should be available only to the app surface.`);
const mentionTool = listedTools.result?.tools?.find((tool) => tool.name === 'search_mentions');
if (!mentionTool?._meta?.['openai/extensions']?.['mentions/search'] || !mentionTool?._meta?.ui?.visibility?.includes('app')) throw new Error('Codex composer mention search is missing.');
const resources = await rpc(21, 'resources/list');
if (!resources.result?.resources?.some((resource) => resource.uri === viewTool._meta.ui.resourceUri) || !resources.result.resources.some((resource) => resource.uri === workspaceTool._meta.ui.resourceUri)) throw new Error('MCP UI resources were not listed.');
const resource = await rpc(22, 'resources/read', { uri: viewTool._meta.ui.resourceUri });
if (resource.result?.contents?.[0]?.mimeType !== 'text/html;profile=mcp-app' || !resource.result.contents[0].text.includes('ui/initialize') || !resource.result.contents[0].text.includes("callTool('post_message'")) throw new Error('MCP UI resource did not load its composer.');
const previousChannelResource = await rpc(220, 'resources/read', { uri: 'ui://await/channel-v3.html' });
if (previousChannelResource.result?.contents?.[0]?.uri !== 'ui://await/channel-v3.html') throw new Error('Older channel cards can no longer load.');
const workspaceResource = await rpc(62, 'resources/read', { uri: workspaceTool._meta.ui.resourceUri });
const workspaceHtml = workspaceResource.result?.contents?.[0];
assert.equal(workspaceHtml?.mimeType, 'text/html;profile=mcp-app', 'Codex workspace UI resource did not load.');
for (const needle of [
  'ui/initialize', "callTool('open_workspace'", "callTool('search_messages'",
  "callTool('get_file_download_link'", "openModal('edit-message'", "openModal('delete-message'",
  "'reaction-picker'", "openModal('leave-channel'", "openModal('archive-channel'",
  "request('ui/download-file'", "request('ui/open-link'", 'ui/update-model-context', 'Ask about',
]) assert.ok(workspaceHtml.text.includes(needle), `Codex workspace UI resource is missing ${needle}.`);
for (const mode of ['inline', 'fullscreen']) assert.ok(workspaceHtml._meta?.['openai/ui']?.availableDisplayModes?.includes(mode), `Codex workspace UI resource does not offer ${mode} display.`);
// Hosts keep the widget URI they first saw, and the server serves the current widget for any
// earlier version. These are the versions connected Codex hosts are known to have cached.
const range = (first, last) => Array.from({ length: last - first + 1 }, (_, index) => first + index);
for (const uri of [...range(16, 23), ...range(63, 81)].map((version) => `ui://await/workspace-v${version}.html`)) {
  const previousWorkspaceResource = await rpc(621, 'resources/read', { uri });
  if (previousWorkspaceResource.result?.contents?.[0]?.uri !== uri || previousWorkspaceResource.result.contents[0].text !== workspaceResource.result.contents[0].text) throw new Error('Previously connected Codex workspace UI resource did not load.');
}
const agentWorkspace = await rpc(63, 'tools/call', { name: 'open_workspace', arguments: {} });
if (agentWorkspace.result?.isError || agentWorkspace.result?.structuredContent?.result?.viewer?.kind !== 'agent' || agentWorkspace.result.structuredContent.result.current?.channel?.id !== workspace.channel_id) throw new Error('Agent workspace entrypoint did not open its first channel.');
for (const [name, args] of [['create_agent', { name: 'Unauthorized child' }], ['add_agent_to_channel', { agent_id: agent.account_id, channel_id: workspace.channel_id }], ['add_channel_member', { account_id: agent.account_id, channel_id: workspace.channel_id }], ['pause_agent', { agent_id: agent.account_id, paused: true }], ['rotate_agent_token', { agent_id: agent.account_id }]]) {
  const rejectedManagement = await rpc(630, 'tools/call', { name, arguments: args });
  if (!rejectedManagement.result?.isError) throw new Error(`Named agent was allowed to use human-only ${name}.`);
}
const liveTicket = await rpc(64, 'tools/call', { name: 'get_live_ticket', arguments: {} });
const ticket = liveTicket.result?.structuredContent?.result?.ticket;
if (liveTicket.result?.isError || !/^[a-f0-9]{64}$/.test(ticket) || liveTicket.result.structuredContent.result.workspace_id !== workspace.id) throw new Error('Live ticket was not issued to the connected identity.');
const liveUrl = `${base.replace(/^http/, 'ws')}/api/workspaces/${workspace.id}/ws?ticket=${ticket}`;
const liveSocket = new WebSocket(liveUrl, { headers: { origin: base } });
const liveReady = await new Promise((resolve, reject) => {
  const timer = setTimeout(() => reject(new Error('Live socket did not connect.')), 5000);
  liveSocket.once('message', (raw) => { clearTimeout(timer); resolve(JSON.parse(String(raw))); });
  liveSocket.once('error', reject);
});
if (liveReady.type !== 'ready' || liveReady.account_id !== agent.account_id) throw new Error('Live socket connected as the wrong identity.');
const replay = new WebSocket(liveUrl, { headers: { origin: base } });
const replayStatus = await new Promise((resolve, reject) => {
  replay.once('unexpected-response', (_request, response) => resolve(response.statusCode));
  replay.once('open', () => reject(new Error('A one-use live ticket was accepted twice.')));
  // The local Vite socket proxy closes rejected upgrades without forwarding the 401.
  replay.once('error', (error) => error.code === 'ECONNRESET' ? resolve('rejected') : reject(error));
});
if (replayStatus !== 401 && replayStatus !== 'rejected') throw new Error(`A used live ticket returned ${replayStatus}.`);
const liveMessage = new Promise((resolve, reject) => {
  const timer = setTimeout(() => reject(new Error('Live message was not delivered.')), 5000);
  liveSocket.on('message', (raw) => { const event = JSON.parse(String(raw)); if (event.type === 'message' && event.message?.body === 'Live OAuth delivery test.') { clearTimeout(timer); resolve(event); } });
});
const livePost = await rpc(65, 'tools/call', { name: 'post_message', arguments: { channel_id: workspace.channel_id, body: 'Live OAuth delivery test.' } });
if (livePost.result?.isError) throw new Error('Live test message could not be posted.');
const delivered = await liveMessage;
if (delivered.message.author_id !== agent.account_id) throw new Error('Live message had the wrong author.');
liveSocket.close();
console.log('✓ One-use live ticket and immediate WebSocket delivery');
const channelView = await rpc(23, 'tools/call', { name: 'show_channel', arguments: { channel_id: workspace.channel_id } });
if (channelView.result?.isError || channelView.result?.structuredContent?.result?.channel?.id !== workspace.channel_id || channelView.result?.structuredContent?.result?.viewer?.name !== 'OAuth Tester Agent') throw new Error(`MCP channel view failed: ${JSON.stringify(channelView.result)}`);
const privateChannel = await json(await fetch(`${base}/api/workspaces/${workspace.id}/channels`, { method: 'POST', headers: authHeaders, body: JSON.stringify({ name: 'Private review', is_private: true }) }));
await json(await fetch(`${base}/api/workspaces/${workspace.id}/collab/boards`, { method: 'POST', headers: authHeaders, body: JSON.stringify({ channel_id: privateChannel.id, name: 'Confidential roadmap' }) }));
await json(await fetch(`${base}/api/workspaces/${workspace.id}/collab/documents`, { method: 'POST', headers: authHeaders, body: JSON.stringify({ channel_id: privateChannel.id, title: 'Confidential notes' }) }));
const initialMentions = await rpc(701, 'tools/call', { name: 'search_mentions', arguments: { query: '' } });
if (initialMentions.result?.isError || !initialMentions.result?.structuredContent?.items?.some((item) => item.name === '#general' && item.uri === `${new URL(base).origin}/w/${workspace.id}/${workspace.channel_id}`) || initialMentions.result.structuredContent.items.some((item) => item.name === '#Private review')) throw new Error('Composer mention search exposed an inaccessible channel or missed general.');
const privateMentions = await rpc(702, 'tools/call', { name: 'search_mentions', arguments: { query: 'Private' } });
if (privateMentions.result?.isError || privateMentions.result?.structuredContent?.items?.length) throw new Error('Composer mention search leaked a private channel.');
const privateWorkMentions = await rpc(706, 'tools/call', { name: 'search_mentions', arguments: { query: 'Confidential' } });
if (privateWorkMentions.result?.isError || privateWorkMentions.result?.structuredContent?.items?.length) throw new Error('Composer mention search leaked private shared work.');
