// One host client can keep independent identities, workspaces, and permission grants.
async function connectionForm(fields, scopes = ['read', 'post', 'files']) {
  authorization.searchParams.set('scope', scopes.join(' '));
  const page = await fetch(authorization, { headers: { cookie: sessionCookie }, redirect: 'manual' });
  const html = await page.text();
  assert.ok(page.ok);
  const handle = html.match(/name="handle" value="([^"]+)"/)?.[1];
  const consentCookie = page.headers.get('set-cookie')?.split(';')[0];
  assert.ok(handle && consentCookie);
  const form = new URLSearchParams({ handle, decision: 'approve', ...fields });
  for (const scope of scopes) form.append('scope', scope);
  return fetch(`${base}/authorize`, { method: 'POST', headers: { cookie: `${sessionCookie}; ${consentCookie}`, 'content-type': 'application/x-www-form-urlencoded', origin: base }, body: form, redirect: 'manual' });
}
async function connect(fields, scopes) {
  const approved = await connectionForm(fields, scopes);
  assert.equal(approved.status, 302, await approved.text());
  const code = new URL(approved.headers.get('location')).searchParams.get('code');
  const token = await json(await fetch(`${base}/oauth/token`, { method: 'POST', headers: { 'content-type': 'application/x-www-form-urlencoded' }, body: new URLSearchParams({ grant_type: 'authorization_code', code, redirect_uri: 'http://127.0.0.1:8765/callback', client_id: client.client_id, code_verifier: verifier, resource: `${base}/mcp` }) }));
  const call = async (name, args = {}) => json(await fetch(`${base}/mcp`, { method: 'POST', headers: { authorization: `Bearer ${token.access_token}`, 'content-type': 'application/json' }, body: JSON.stringify({ jsonrpc: '2.0', id: 401, method: 'tools/call', params: { name, arguments: args } }) }));
  return { token, call };
}
