const refreshedToken = await json(await fetch(`${base}/oauth/token`, { method: 'POST', headers: { 'content-type': 'application/x-www-form-urlencoded' }, body: new URLSearchParams({ grant_type: 'refresh_token', refresh_token: agentAgain.token.refresh_token, client_id: client.client_id, resource: `${base}/mcp` }) }));
const refreshedProfile = await json(await fetch(`${base}/mcp`, { method: 'POST', headers: { authorization: `Bearer ${refreshedToken.access_token}`, 'content-type': 'application/json' }, body: JSON.stringify({ jsonrpc: '2.0', id: 413, method: 'tools/call', params: { name: 'get_profile', arguments: {} } }) }));
assert.equal(refreshedProfile.result?.structuredContent?.id, originalProfile.id);
// Access revocation still invalidates all credentials for the revoked agent, not unrelated connections.
await json(await fetch(`${base}/api/workspaces/${workspace.id}/agents/${defaultContext.agent.id}/revoke`, { method: 'POST', headers: authHeaders }));
assert.equal((await fetch(`${base}/mcp`, { method: 'POST', headers: { authorization: `Bearer ${defaultAgent.token.access_token}`, 'content-type': 'application/json' }, body: JSON.stringify({ jsonrpc: '2.0', id: 414, method: 'initialize' }) })).status, 401);
assert.equal((await otherHuman.call('get_profile')).result.structuredContent.id, otherHumanProfile.id);
console.log('✓ Independent OAuth connections, automatic agent defaults, stable host profiles, refresh, denial, and workspace isolation');
